func usage() {
	fmt.Println("usage: contractsentinel [demo|version|help]")
	fmt.Println("       contractsentinel audit --input <file> --store <dir>")
	fmt.Println("       contractsentinel report --store <dir> --id <report-id>")
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "error:", err)
	os.Exit(1)
}

